        [
            [
                "עד שתתגלגל. פי' עד שתתערב: \n",
                "ותטמטם. פי' שידבקו חלקם קצתם בקצתם עד שיהיו גוף אחד: \n",
                "האוכל ממנו חייב מיתה. לפי שהוא טבל והטבל במיתה: \n",
                "כיון שהיא נותנת המים מגבהת חלתה. ואף על פי שנשאר מן הקמח בעריבה קצת שלא נלוש ולא נתערב ובתנאי שלא יהיה באותו הקמח שלא נלוש ולא נתערב שיעור חמשה רבעים שהוא שיעור חלה וכשאמר הרי זו חלה על העיסה ועל השאור ועל הקמח שנשתייר בה לכשתעשה כלה תתקדש זו שבידו לשם חלה הרי זה מותר וכן נתבאר בגמרא: \n"
            ],
            [
                "נדמעה. פירוש שנתערבה בה התרומה וכבר בארנו (תרומות פ\"ח מ\"ה ולעיל פ\"א מ\"ד) כי המדומע פטור מן החלה: ואמר תעשה בטהרה ענינו שתגמר כמות שהיא ולא יקפיד בספק טומאה שנולד: \n"
            ],
            [
                "ההקדש אינו חייב בחלה למאמר הש\"י תרימו תרומה ואמר בספרי את שמורם ממנו קודש והנשאר חול ולא שזה וזה קודש וזה המאמר כולו מבואר כשתבין כל מה שהקדמנו בזו הסדר: \n"
            ],
            [
                "זו הלכה כבר קדמנו לדבר עליה בפרק רביעי מפאה ולשם נשנית אות באות: \n"
            ],
            [
                "זה המאמר מבואר היטב: \n"
            ],
            [
                "נעשית עד שלא נתגייר.רוצה בו נתגלגלה בחטים ונטמטמה בשעורים: \n",
                "ואם נולד ספק אם קודם שנתגייר נעשית או אחר שנתגייר חייבת בחלה והאוכל אותה חלה בשוגג אינו חייב חומש לפי שהוא ספק והמוציא מחבירו עליו הראיה וכבר ביארנו כי החלה האמיתית חייבין בה חומש: \n",
                "ור' עקיבא אומר הכל הולך אחר הקרימה בתנור. אם נתגייר קודם שיקרמו פני הפת בתנור חייב בחלה לפי שר' עקיבא סובר כי החלה מוציאין משיקרמו פני הפת ולדעתו זה היה שעת הוצאת חלה וכן נראה מדעתו בספרי אמר לשם אין מפרישין עד שתגמר מלאכתה איזה הוא גמר מלאכתה קרימתה בתנור דברי ר' עקיבא וקרימה הוא שיקפה פני הפת ויהיה לו כמין קליפה ואין הלכה כרבי עקיבא: \n"
            ],
            [
                "כבר קדם לנו כי החלה אינה חייבת אלא מחמשת המינין וכמו כן אין אדם יוצא ידי חובתו בפסח אלא בחמשת המינים ואין האורז מכללם: \n"
            ],
            [
                "אם יש לו פרנסה ממקום אחר מוציא לפי חשבון. ביאור זה כאשר אגיד לך והוא שמביא אדם קמח שיעורו כשיצרפו לאותו שאור שלקח מעיסה שלא הורמה חלתה שיהיה הכל חמשה רבעים שהוא שיעור חלה ואחר כך יערב הכל ומוציא ממנו החלה החייבת לחמשה רבעים ואם אין לו מה שיצרף תהיה כל העיסה טבל ויוציא ממנה החלה החייבת לה אילו היתה כולה טבולה לחלה וזהו אמרם מוציא חלה אחת על הכל: \n"
            ],
            [
                "זיתי מסיק. הם הזיתים שמלקטין בעלי בתים שהם בעלי הקרקעות וכבר ביארנו פעמים (פאה פרק ח מ\"א) כי לקיטת הזיתים יקרא בלשון חכמים מסיקה וזיתי נקוף הם הזיתים שמלקטים העניים והעד כנוקף זית שנים שלשה גרגרים (ישעיהו י״ז:ו׳) זיתי נקוף והעוללות אינן חייבין במעשרות כמו שבארנו במסכת פאה (פ\"א משנה ו) וכשנתערבו זיתי נקוף שאינן חייבות בתרומה ובמעשרות עם זיתי מסיק שהן חייבות בהם אם יש אצלו זיתים אחרים מלבד אותן המעורבות יוציא מהם המעשרות והתרומה החייבות לאותן זיתי מסיק המעורבות עם זיתי נקוף הפטורות וזהו ענין אמרם לפי חשבון ואם אין אצלו זיתים אחרים יוציא מן הזיתים המעורבים תרומה ותרומת מעשר החייבים לכל ונחשב הכל זיתי מסיק ומה שישאר מן הדבר המעורב יוציא ממנו מעשר ראשון ומעשר שני לפי חשבון כלומר לפי מה שיש באותו הדבר המעורב מזיתי מסיק בלבד ושיעור ההלכה כך ומפריש מן השאר מעשר ראשון ומעשר שני לפי חשבונו ומה שחייבנו שנוציא התרומה ותרומת מעשר על הכל לפי שיש בהם עון מיתה כמו שבארנו בתחלת דמאי ובלי ספק שיוכל לחזור וליקח ולקנות מן העניים זיתי נקוף או העוללות המעורבות בזיתיו או בענביו על הדרך שנזכר בפאה: \n"
            ],
            [
                "אוסר כל שהוא מין במינו. כיצד כגון שיתערב חטה בחטה ואורז באורז ושלא במינו בנותן טעם כגון שיתערב חטים באורז וכיוצא בו: \n"
            ]
        ],
        [
            [
                "זו ההלכה על דעת בית הלל שאומרים מקביים חלה כמו שיתבאר בעדיות וכבר בארנו אנחנו במה שקדם (לעיל פ\"ב מ\"ו) שיעור חלה והכוונה בזו ההלכה שיהיה בשתי העיסות שיעור חלה: \n"
            ],
            [
                "זה הצירוף אין ענינו שתתערב העיסה כולה ויהיה הכל אחד לפי שכבר קדם כי חמשת המינים מצטרפין זה עם זה אבל ענינו שיסדרו עיסה אצל עיסה אחרת ותדבק בה כמו שאמר נגעו זה בזה ורוצה באמרן שאר המינים שאר חמשת מינין והם שבולת שועל וכוסמין ושיפון והלכה כר' יוחנן בן נורי: \n"
            ],
            [
                "כבר קדם לנו כי האורז והתרומה אינן חייבין בחלה וזהו כשהן נושכין זו בזו ולא יצטרך לשנות לך ענין אמרם קביים שיעור חלה כי כבר זכרנוהו: \n"
            ],
            [
                "וחכמים אוסרים. נאמר על העיקר שקדם במסכת תרומות (פ\"א מ\"ה) אין מפרישין מן החדש על הישן ומן הישן על החדש: ואמר מן הקב רוצה בו פחות משיעור חלה לדעת חכמים אבל בית שמאי אומר מקב חלה כמו שיתבאר בעדיות ונטה ר' עקיבא לדעת שמאי מעט והלכה כחכמים: \n"
            ],
            [
                "ר' עקיבא פוטר על העיקר שקדם לך מדעתו כי מי שהוציא חלה מקב אחד נקראת חלה וחכמים מחייבין לפי שהם אומרים במי שהוציאה מקב אחד אינה חלה: \n",
                "נמצא חומרו קולו. חזר על דעת ר\"ע לפי שחומרא שהחמיר ואמר בחלה שהוציא מקב אחד קדש ואסורה לזרים הכריחו לומר בשני קבים הנזכרים בכאן פטורה מן החלה וזו היא קולא: \n"
            ],
            [
                "אומר בכאן שלוקח אדם שיעור מן העיסה והוא טהור ומצניעו להיות חלה על עיסות אחרות שילוש מן הדמאי אפי' יהיו אותן העיסות טמאות לפי שהעיקר אצלנו מה שזכר חלת דמאי ניטלת מן הטהור על הטמא ושלא מן המוקף ואמר עד שתסרח חוזר על כדי חלה שהוציא בטהרה לפי שהוא מפריש עליה עד שתסרח ותפסד ולא תהיה ראויה לאכילת אדם: \n"
            ],
            [
                "כבר קדם לנו כי סוריא הם הארצות שכבש דוד שלא מארץ ישראל וכבר בארנו במסכת דמאי (פ\"ו מי\"א) שפירות סוריא אינן חייבות במעשרות אלא למי שלקט אותם פירות מקרקע שלו ואחוזתו ובארנו טעם בזה ואומר בכאן שאם היו ישראל ונכרי שותפין בקרקע מארץ סוריא ר\"א מחייב אותם במעשרות כי סוריא לדעתו כמו א\"י בזה הענין כיון שיש לו שותפות בקרקע ונתחייב במעשרות רבן גמליאל פוטר לפי שהיא אצלו קרוב מחוצה לארץ ואינו חייב במעשרות עד שיהיה הקרקע כולו שלו ולא יהיה לנכרי חלק בו כמו שבארנו במסכת דמאי: ומה שאמר ר\"נ שתי חלות בסוריא. נמשך אחר עיקרו כי סוריא דיניה קרובים מדיני חוצה לארץ וחייב אדם להוציא בה שתי חלות מן העיסה כמו שהוא חייב בחוצה לארץ האחת תשרף מפני שהיא טמאה לפי שהיא כחוצה לארץ והשני תנתן לכהן כדי שלא תשתכח תורת חלה מישראל כמו שנתבאר לקמן ועוד יתבאר זה במקומות כי עפר חוצה לארץ שורפין עליו תרומה: \n",
                "ורבי אליעזר אומר חלה אחת. לפי שסוריא אצלו כמו ארץ ישראל ברוב הדינים ואינו סובר שעפרה מטמא כמו חוצה לארץ על כן אינה חייבת אלא בחלה אחת והנהיג העם זמן לקולא כשתי הדעות והוא שהיו מחייבים בסוריא חלה אחת ופוטרין פירות האריסים מן המעשרות ואחר כך חזרו לנהוג כדברי ר\"ג והלכה כר\"ג בשני המאמרים: \n"
            ],
            [
                "שלש ארצות לחלה. ענינו כי לשלשה חלקים תחלק הארץ לענין חיוב חלה. א\"י כולה וגבולה עד כזיב והיא הארץ שהחזיקו בה עולי בבל כמו שנתבאר בפרק ששי (מ\"א) משביעית והיא הארץ שנתקדשה קדושה שניה בעליית עזרא היא חייבת בחלה אחת ותנתן לכהן: \n",
                "מכזיב ועד הנהר ועד אמנה. והיא א\"י שהחזיקו בה עולי מצרים ולא נתקדשה בימי עזרא אבל נשארו שם הנכרים שוכנים היא חייבת שתי חלות אחת לשריפה מפני שהיא תרומה טמאה ויש לה שיעור לפי שהיא מן התורה למאמר הש\"י והיה באכלכם מלחם הארץ (במדבר ט״ו:י״ט) ונאמר זה כשהיו אוכלין המן וכשאכלו הדגן נתחייבו בחלה ולפיכך צריך להוציא חלה כשיעור שזכרנו והוא חלק מכ\"ד או חלק מארבעים ושמונה כמו שנתבאר וחלה שניה לתתה לכהן ואין לה שיעור אלא איזה שיעור שירצה המוציא לפי שהיא מדברי הסופרים והתקינו זה כדי שלא יחשוב אדם שתרומה טהורה תשרף כשרואין ששורפין זאת החלה שלא נטמאת טומאה מפורסמת: \n",
                "מהנהר ועד אמנה ולפנים. ר\"ל שאר הארץ כולה שהיא ארץ העמים והיא חוצה לארץ ושוכנים בה ישראל אחר גלותם מארצם ארץ הצבי יתחייב בה גם כן שתי חלות אבל שתיהם מדרבנן ולפיכך נתנו השיעור לחלת הכהן ושל אור אין לה שיעור וכן אמרו הואיל וזו וזו מדבריהם מוטב לרבות בנאכלות ולא לרבות בנשרפות: ואמרו וטבול יום אוכלה. ענינו חלת חוצה לארץ שאין לה שיעור ורבי יוסי מתיר לבעל קרי לאוכלה: \n",
                "ואסורה לזבים ולזבות לנדות וליולדות. לחוזק טומאתן לפי שטומאה יוצאה עליהן מגופן ואמרם בגמ' אין תרומת חוצה לארץ אסורה אלא למי שטומאה יוצאה עליו מגופו ר\"ל באיש עד שיראה קרי ובאשה עד שתראה דם והוא היקש וסברא אמתית שדמה אותה בזו: \n",
                "הראשונה הנשרפת שהיא מותרת לאכילה לכהן קטן אבל לכהן גדול בשנים שהוא טמא טומאת הגוף אסור לאכלה אבל תשרף ולפיכך ראוי לך לדעת כי כשיהיה כהן קטן או גדול שטבל נמצא בחוצה לארץ לא נצטרך להוציא שתי חלות אלא נוציא אחת כשיעור ונותן אותה לכהן הקטן ואוכלה כולה ואם לא יהיה לנו כהן אלא מי שטומאה יוצאה עליו מגופו והוא בטומאתו אז נוציא שתי חלות אחת אין לה שיעור ותשרף כמו שבארנו ואחת יש לה שיעור ותנתן לאיזה כהן שיזדמן לו ואוכלה כדי שלא תשתכח תורת חלה מישראל ושיעור זו החלה חלק מארבעים ושמנה לפי שהיא טמאה רוצה לומר אותה העיסה שנילושה בארץ טמאה: ואמרם ונותן לכל כהן. ענינו בין שהיה חבר בין שהיה עם הארץ לפי שאינה כל כך באזהרה שלא תנתן לעם הארץ ונחוש שמא יאכלנו בטומאה כיון שהיא טמאה בארץ העמים ואין הלכה כרבי יוסי וממה שאתה צריך לידע מה שאמרתי בפרק רביעי מבכורות תרומת חוצה לארץ אוכל והולך ואחר כך מפריש ענינו שהוא מותר לו ושם נאמר תרומת חוצה לארץ אין בה משום כהן המסייע בבית הגרנות: \n"
            ],
            [
                "אמרו בגמרא הבכורים והבכורות לאנשי משמר והשאר לכל כהן רצו באמרם לכל כהן שלא פרט בהם כהן תלמיד חכם מעם הארץ אלא על דרך הטוב והיפה לאומרו הש\"י ונתתם ממנו את תרומת ה' לאהרן הכהן (במדבר י״ח:כ״ח) ואמרו בספרי מה אהרן חבר אף כל חבירים מכאן אמרו אין נותנין מתנות כהונה אלא לחבר וזה הדין הוא חיוב במקצת המתנות כמו שיתבאר בזה הפרק ובשאר המתנות יהיה הכל חוזר לרצון הנותן אבל שיהיה אסור לתתם לעם הארץ לא: \n",
                "והחרמים הוא מאמר הש\"י לאהרן כל חרם בישראל לך יהיה (שם) רומז לאמרו יתעלה אך כל חרם אשר יחרים איש לה' וגו' (ויקרא כ״ז:כ״ח) וכמו כן שדה אחוזה לא יחד בו כהן ואמר יתעלה ואם משדה אחוזתו יקדיש איש לה' וגו' (שם): \n",
                "הבכורות. רוצה בו בכור בהמה טהורה: \n",
                "ופדיון הבן הוא חמשה סלעים שפודין בהם בכור האדם: \n",
                "ופדיון פטר חמור הוא אמרו יתעלה ופטר חמור תפדה בשה (שמות י״ג:י״ג) והשם ית' רמז באמרו (במדבר י״ח:ט״ו) ואת בכור הבהמה הטמאה תפדה וכבר כלל הכתוב אלו השלשה מינין מן הבכורות בפסוק אחד ואמר (שם) כל פטר רחם לכל (בשר) אשר יקריבו לה' באדם ובבהמה וגו': \n",
                "ותזרוע והלחיים והקיבה. הם הנקראות מתנות בכל המשנה והוא אמרו יתעלה ונתן לכהן הזרוע והלחיים והקיבה (דברים י״ח:ג׳): \n",
                "וראשית הגז. הוא אמרו (שם) וראשית גז צאנך תתן לו ועוד יתבאר דיני המתנות וראשית הגז במסכת חולין וכמו כן נבאר דיני שדה חרמים ושדה אחוזה במסכת בכורות. וכבר בארנו פעמים בזה הסדר ששמן שרפה קורין לשמן תרומה שנטמא. והטעם שלא נקדים באלו המתנות כהן חבר על זולתו לפי שאין בהם קדושה ולא נחוש שמא יטמאו אותם עם הארץ. ואמר וקדשי המקדש ענינו שהן ניתנין לכל כהן מאנשי המשמר לפי שאנחנו לא נקדים אנשי המשמר קצתם על קצתם. וקדשי מקדש הם עשרה חטאת בהמה וחטאת העוף והאשם ודאי והאשם תלוי וזבחי שלמי צבור ולוג שמן של מצורע ושתי הלחם ולחם הפנים ושירי מנחות ושירי העומר. ומפני זה נקראין קדשי מקדש לפי שאסור לכהנים לאכול דבר מאלו העשרה אלא בעזרה ודע כי מתנות כהונה הם כולן עשרים וארבע עשרה במקדש והם אותם שאמרתי לך וארבעה שאין הכהנים זוכים בהם אלא בירושלים בלבד והם הבכורות והבכורים ומורם מתודה ואיל נזיר ועורות הקדשים. הבכורות והביכורים כבר בארנו שהם ביארו בגמ' שהם ניתנין לאנשי משמר ומורם מתודה ואיל נזיר וכמו כן עורות קדשים אינן ניתנות לכל כהן אבל לוקח אותם הכהן המקריב אותו הזבח וכן בא הכתוב בעורת קדשים (ויקרא ז׳:ח׳) והכהן המקריב את עולת איש עור העולה אשר הקריב לכהן לו יהיה ואמר במורם מתודה לכהן הזורק את דם השלמים לו יהיה (שם) ואמר במורם מאיל נזיר והניף אותם הכהן תנופה לפני ה' קודש הוא לכהן (במדבר ו׳:כ׳) ולמדנו שהכהן המניף הוא האוכל אותה. ויש מהם עשר מתנות זוכים בהם הכהנים בכל ארץ ישראל והם אותם שאמרו בהם עשר בגבולין והם תרומה ותרומת מעשר וחלה וראשית הגז והמתנות ופדיון הבן ופדיון פטר חמור ושדה אחוזה ושדה חרמים וגזל הגר. ומצינו בזו הלכה מאלו העשר מתנות שש מתנות ואמרו שהן ניתנין לכל כהן נשארו ארבעה והם תרומה ותרומת מעשר וחלה וגזל הגר. ותרומה ותרומת מעשר וחלה אינן ניתנין לעם הארץ בשום פנים מפני שהוא חשוד על הטומאה ושמא יטמאם ויאכלם וכן גזל הגר אינו ניתן אלא לכהן המקריב איל האשם והוא אמרו ית' ואם אין לאיש גואל להשיב האשם אליו האשם המושב לה' לכהן מלבד איל הכפורים אשר יכפר בו עליו (שם ה) הורנו בזה הפסוק שלאותו כהן המקריב בעבורו איל האשם נותנין לו הדבר הגזול ופירשו זה הפסוק במי שגזל גר באמרו הש\"י ואם אין לאיש גואל וזה אי אפשר אלא בגר כי לישראל לא יחסר לו יורש לעולם לאמרו ונתתם את נחלתו לשארו וגו' (שם כז) ואמרו רז\"ל נחלה ממשמשת ועולה עד ראובן כמו שנבאר בב\"ב: \n",
                "ר' יהודה אוסר בבכורים. שינתנו לאיזה כהן שיזדמן וכבר זכרנו שהם ראוין לאנשי משמר ועוד יתבאר דיניהם במסכת בכורים: \n",
                "וכרשיני תרומה מתיר ר\"ע לתתם לכל כהן לפי שהם מאכל בהמה ואם נטמאו לא נקפיד להם וחכמים אוסרין לפי שהיו נאכלים בימי הרעב ונחוש שמא יאכלם בטומאה ולפיכך אינן ניתנין אלא לחבר כדין כל תרומה וזה הוא ענין אמרם אימתי גזרו על הכרשינין בימי רעבון *והלכה כחכמים: \n"
            ],
            [
                "העיקר אצלנו אין מביאין תרומה מחוץ לארץ לארץ ואמרו בגמרא באלו התרומות הבאות לארץ ישראל לאכלם אי אפשר שלא יהיו אומרים ראינו תרומה טמאה נאכלת לפי שהיא מחוצה לארץ. לשרפה אי אתה יכול שלא יהיו אומרים ראינו תרומה טהורה נשרפת לפי שלא נטמאה בטומאה מפורסמת אלא בעפר חוצה לארץ ואין כל אדם יודע בזאת הטומאה. להחזירה למקומה אי אפשר שלא יהו אומרים ראינו תרומה יוצאה מהארץ לחוצה לארץ כיצד הוא עושה מניחה עד ערב הפסח ושורפה וזהו ענין המעשה שנעשה בתרומות אלכסנדריא ואמר לא קבלו מהם: \n"
            ],
            [
                "אמרו בספרי יכול יהא אדם מעלה בכורות מחוצה לארץ לארץ ת\"ל (דברים י״ד:כ״ג) ואכלת לפני ה' אלהיך מעשר דגנך תירושך ויצהרך ובכורות בקרך וצאנך ממקום שאתה מביא מעשר דגן אתה מביא בכורות מחוצה לארץ שאין אתה מביא מעשר דגן אין אתה מביא בכורות: ואמרם הביא בכורי יין ושמן ולא קבלו ממנו. היא הסברא האמתית ועוד יתבאר לך זה בבכורים שאין מביאין בכורים משקין והמאמר שכתבנו לך בתרומות (פי\"א מ\"ג) אין מביאין בכורים משקין אלא היוצא מן הזיתים ומן הענבים בלבד הוא דעת ר' יהודה לבדו שהוא למד בכורים מתרומה כאשר ביארו בגמרא וכבר זכרנו זה בתרומה: \n",
                "אף הוא העלה את בניו. אלו הבנים קטנים היו בלי ספק ולא היו חייבין לעלות אלא בפסח ראשון שהכל חייבין בראיה לאמרו יתעלה (שמות כ״ג:י״ז) שלש פעמים בשנה יראה כל זכורך: \n",
                "אפמיא. שם מקום בארץ סוריא ופרווד של ירושלים מגרשי ירושלים וכפריה תרגום מגרשה פרוודה וכבר בארנו בתחלת דמאי כי מי שקנה קרקע בסוריא נתחייב במעשרות באותו הקרקע וזהו עיקר אותו המאמר: \n"
            ]
        ]
